//! Exact ID values, operation brands and actual ordinary tree membership.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><div id=mount></div></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://identifier-lookup.test/",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0,"{}",page.report());(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn identifier_lookup_canonical_interface_brands_required_domstring_and_ignored_extras(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var fragment=document.createDocumentFragment(),docMethod=Document.prototype.getElementById,fragMethod=DocumentFragment.prototype.getElementById,touched=0;if(docMethod===fragMethod||document.getElementById!==docMethod||fragment.getElementById!==fragMethod||document.createElement('span').getElementById!==undefined)throw 'separate native operations and no Element exposure';for(var pair of [[document,Document.prototype,docMethod,fragment],[fragment,DocumentFragment.prototype,fragMethod,document]]){var root=pair[0],method=pair[2],desc=Object.getOwnPropertyDescriptor(pair[1],'getElementById');if(method.name!=='getElementById'||method.length!==1||!desc.writable||!desc.enumerable||!desc.configurable)throw 'canonical descriptor';for(var bad of [{},window,Node.prototype,pair[1],pair[3],document.createElement('span')]){var caught=false;try{method.call(bad,{toString:function(){touched++;return 'x';}});}catch(e){caught=e instanceof TypeError;}if(!caught||touched)throw 'interface brand before conversion';}var caught=false;try{method.call(root);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'required argument';var caught=false;try{method.call(root,Symbol());}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'Symbol DOMString';var parent=root===document?document.body:root;for(var spelling of ['null','undefined','1']){var el=document.createElement('span');el.setAttribute('id',spelling);parent.appendChild(el);var value=spelling==='null'?null:spelling==='undefined'?undefined:BigInt(1);if(method.call(root,value,{toString:function(){touched++;throw 'extra';}})!==el)throw 'ordinary DOMString conversion and ignored extras';}if(method.call(root,'')!==null||touched)throw 'empty ID and extra conversion';}
"#);}
#[test]
fn identifier_lookup_inert_owners_exact_units_tree_order_current_moves_and_namespaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var html=document.implementation.createHTMLDocument('owner'),xml=document.implementation.createDocument(null,'Root'),generic=new Document(),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template');for(var owner of [html,xml,generic,template.content.ownerDocument]){var root=owner.body||owner.documentElement;if(!root){root=owner.createElement('Root');owner.appendChild(root);}var a=owner.createElement('span'),b=owner.createElementNS('urn:element','e:Other'),replacement=owner.createElement('span'),upper=owner.createElement('span');a.setAttribute('id','item\ud800');b.setAttribute('id','item\ud800');replacement.setAttribute('id','item\ufffd');upper.setAttributeNS(null,'ID','uppercase-is-not-id');replacement.setAttributeNS('urn:attr','id','namespaced-is-not-id');root.appendChild(a);root.appendChild(b);root.appendChild(replacement);root.appendChild(upper);if(owner.getElementById('item\ud800')!==a||owner.getElementById('item\ufffd')!==replacement||owner.getElementById('Item\ud800')!==null||owner.getElementById('uppercase-is-not-id')!==null||owner.getElementById('namespaced-is-not-id')!==null||owner.getElementById('')!==null)throw 'exact ID source and namespace';root.insertBefore(b,a);if(owner.getElementById('item\ud800')!==b)throw 'current tree order';root.removeChild(b);if(owner.getElementById('item\ud800')!==a)throw 'detached root excluded';var target=new Document();target.adoptNode(a);if(owner.getElementById('item\ud800')!==null||target.getElementById('item\ud800')!==null||a.ownerDocument!==target)throw 'owner is not ancestry';target.appendChild(a);if(target.getElementById('item\ud800')!==a)throw 'actual new root';}
"#);}
#[test]
fn identifier_lookup_fragment_template_roots_author_getters_and_conversion_reentry(){let(mut d,mut f,mut p)=fixture();p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),root=owner.createElement('root');owner.appendChild(root);var a=owner.createElement('span'),b=owner.createElement('span');a.setAttribute('id','same');b.setAttribute('id','same');root.appendChild(a);root.appendChild(b);var calls=0;if(owner.getElementById({toString:function(){calls++;root.insertBefore(b,a);return 'same';}})!==b||calls!==1)throw 'conversion before current tree walk';Object.defineProperty(Element.prototype,'id',{configurable:true,get:function(){throw 'author id';}});Object.defineProperty(Node.prototype,'childNodes',{configurable:true,get:function(){throw 'author children';}});if(owner.getElementById('same')!==b)throw 'native facts';var host=owner.createElementNS('http://www.w3.org/1999/xhtml','template'),inside=host.content.ownerDocument.createElement('span');inside.setAttribute('id','dedicated\ud800');host.content.appendChild(inside);root.appendChild(host);if(host.content.getElementById('dedicated\ud800')!==inside||owner.getElementById('dedicated\ud800')!==null||host.content.ownerDocument.getElementById('dedicated\ud800')!==null)throw 'dedicated content and associated document are separate roots';var expected={},caught=false;try{owner.getElementById({toString:function(){b.setAttribute('id','effect');throw expected;}});}catch(e){caught=e===expected;}if(!caught||owner.getElementById('effect')!==b||owner.getElementById('same')!==a)throw 'author effects survive conversion error';
"#);}
#[test]
fn identifier_lookup_native_fragment_splice_and_saved_child_origin_before_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var fragment=document.createDocumentFragment(),leaf=document.createElement('span');leaf.setAttribute('id','fragment-native');fragment.appendChild(leaf);if(fragment.getElementById('fragment-native')!==leaf||document.getElementById('fragment-native')!==null)throw 'physical native fragment';document.body.appendChild(fragment);if(fragment.getElementById('fragment-native')!==null||document.getElementById('fragment-native')!==leaf)throw 'actual spliced roots';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Document.prototype.getElementById,calls=0,query={toString:function(){calls++;return 'fragment-native';}};if(saved.call(document,query)!==leaf||calls!==1||w.document.getElementById('fragment-native')!==null)throw 'real child operation and root';
"#);p.set_location(&crate::navigation::address("https://other-identifier-lookup.test/",&crate::navigation::Location::home()).unwrap());let before=(d.nodes.len(),p.state.retained,p.state.dom_commits);assert_eq!(p.console_eval(&mut d,&mut f,"saved.call(document,query);").errors,1);assert_eq!((d.nodes.len(),p.state.retained,p.state.dom_commits),before);run(&mut d,&mut f,&mut p,"if(calls!==1)throw 'origin precedes conversion';");}
